const jobs = new Map(); // job_id -> status ('running' | 'cancelled')

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job with the given job_id. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by job_id. Changes the job to cancelled. Rejects missing jobs or already-cancelled jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Identifier of the job to cancel.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

function requireJobId(args) {
  if (args == null || typeof args.job_id !== 'string' || args.job_id.length === 0) {
    const err = new Error('job_id is required and must be a non-empty string');
    err.code = -32602;
    throw err;
  }
  return args.job_id;
}

function ok(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'start_job': {
      const job_id = requireJobId(args);
      if (jobs.get(job_id) === 'running') {
        const err = new Error(`Job ${job_id} is already running`);
        err.code = -32602;
        throw err;
      }
      jobs.set(job_id, 'running');
      return ok(`Job ${job_id} is running`);
    }
    case 'cancel_job': {
      const job_id = requireJobId(args);
      const status = jobs.get(job_id);
      if (status === undefined) {
        const err = new Error(`Job ${job_id} not found`);
        err.code = -32602;
        throw err;
      }
      if (status === 'cancelled') {
        const err = new Error(`Job ${job_id} is already cancelled`);
        err.code = -32602;
        throw err;
      }
      jobs.set(job_id, 'cancelled');
      return ok(`Job ${job_id} is cancelled`);
    }
    default: {
      const err = new Error(`Unknown tool: ${name}`);
      err.code = -32601;
      throw err;
    }
  }
}
